-- Security Hypotheses (v0.5 Strategic VulnLLM Layer)
-- Stores structured hypotheses generated by VulnLLM reasoning over the attack surface graph.
-- CRITICAL ARCHITECTURAL RULE: A hypothesis is NOT a finding.
-- Hypotheses are stored here and only promote to confirmed findings if deterministic
-- ToolAdapter scanners and verification probes prove reproducible evidence.

CREATE TABLE IF NOT EXISTS security_hypotheses (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    investigation_id    UUID NOT NULL REFERENCES programs(id) ON DELETE CASCADE,
    category            TEXT NOT NULL,
    target              TEXT NOT NULL,
    rationale           TEXT NOT NULL,
    confidence          DOUBLE PRECISION NOT NULL,
    suggested_actions   JSONB NOT NULL DEFAULT '[]',
    required_evidence   JSONB NOT NULL DEFAULT '[]',
    status              TEXT NOT NULL DEFAULT 'pending',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    resolved_at         TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_hypotheses_investigation_id ON security_hypotheses(investigation_id);
CREATE INDEX IF NOT EXISTS idx_hypotheses_status ON security_hypotheses(status);
CREATE INDEX IF NOT EXISTS idx_hypotheses_category ON security_hypotheses(category);
CREATE INDEX IF NOT EXISTS idx_hypotheses_created_at ON security_hypotheses(created_at);
